Early Exits with return()

safe_ratio &lt;- function(num, den) {
  if (den == 0) {
    return(NA)
  }
  num / den
}

safe_ratio(10, 4)

[1] 2.5

safe_ratio(10, 0)

[1] NA



return() stops the function immediately: use it for early exits.
Otherwise let the last line be the result (the tidyverse style).

Custom Error Messages with stop()

bmi &lt;- function(weight_kg, height_m) {
  if (any(height_m &gt; 3, na.rm = TRUE)) {
    stop("height_m looks like centimeters; divide by 100 first")
  }
  weight_kg / height_m^2
}

bmi(70, 175)

Error in `bmi()`:
! height_m looks like centimeters; divide by 100 first








Tip


A loud error that says how to fix it beats a silent BMI of 0.0023 that flows into your paper.

A Function That Returns a Table

summarize_continent &lt;- function(data, ct, yr = 2008) {
  data |&gt;
    filter(year == yr, continent == ct) |&gt;
    summarize(
      continent   = ct,
      n_countries = n(),
      median_le   = median(life_expectancy, na.rm = TRUE)
    )
}

summarize_continent(gm, "Asia")

# A tibble: 1 × 3
  continent n_countries median_le
  &lt;chr&gt;           &lt;int&gt;     &lt;dbl&gt;
1 Asia               46      71.7

if: Run Code Conditionally

sbp &lt;- 165

if (sbp &gt;= 180) {
  print("Hypertensive crisis: seek care immediately")
} else if (sbp &gt;= 140) {
  print("Stage 2 hypertension")
} else if (sbp &gt;= 130) {
  print("Stage 1 hypertension")
} else {
  print("Not hypertensive")
}

[1] "Stage 2 hypertension"



The condition must be a single TRUE or FALSE.
Branches are checked top to bottom; the first match wins: order matters!

AI Corner: The Unnecessary Loop
Asked to flag high-mortality countries in df, an AI wrote:

df &lt;- gm |&gt; filter(year == 2008)

flags &lt;- c()
for (i in 1:nrow(df)) {
  if (is.na(df$child_mortality[i])) {
    flags &lt;- c(flags, NA)
  } else if (df$child_mortality[i] &gt; 50) {
    flags &lt;- c(flags, "high")
  } else {
    flags &lt;- c(flags, "low")
  }
}

fct_reorder(): Order Levels by a Statistic
The #1 factor trick for readable plots: order categories by their value, not alphabetically.

library(ggplot2)

gm |&gt;
  filter(year == 2008) |&gt;
  drop_na(life_expectancy, region) |&gt;
  group_by(region) |&gt;
  summarize(mean_le = mean(life_expectancy)) |&gt;
  ggplot(aes(x = mean_le, y = fct_reorder(region, mean_le))) +
  geom_col(fill = "steelblue") +
  labs(y = NULL, x = "Mean life expectancy (2008)")


Bars now rise in order: instantly readable.

